import json

def parse_selection(raw, count):
    try:
        data = json.loads(raw)
    except ValueError:
        return None
    if not isinstance(data, dict):
        return None
    numbers = data.get("paragraphs")
    if not isinstance(numbers, list) or not 1 <= len(numbers) <= 3:
        return None
    result = []
    for n in numbers:
        if type(n) is not int or not 1 <= n <= count:
            return None
        if n not in result:
            result.append(n)
    return result
